import{_ as i,a0 as n,w as r,s as d,I as p,x as e,a1 as a,A as o,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"GIMP 3.0 中值得期待的 8 項新功能和改進 | LCTT x X-CMD","titleTemplate":false,"description":"GIMP 3.0 中值得期待的 8 項新功能和改進 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GIMP 3.0 中值得期待的 8 項新功能和改進 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GIMP 3.0 中值得期待的 8 項新功能和改進 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211112 8 New Features - Improvements to Expect in GIMP 3.0 Release","title":"GIMP 3.0 中值得期待的 8 項新功能和改進","tag":"202111","desc":""},"relativePath":"202111/20211112 8 New Features - Improvements to Expect in GIMP 3.0 Release.md","filePath":"[post].md"}'),m={name:"202111/20211112 8 New Features - Improvements to Expect in GIMP 3.0 Release.md"};function P(I,t,u,G,w,f){const s=n("Link");return r(),d("div",null,[t[25]||(t[25]=p("h1",{id:"gimp-3-0-中值得期待的-8-項新功能和改進",tabindex:"-1"},[e("GIMP 3.0 中值得期待的 8 項新功能和改進 "),p("a",{class:"header-anchor",href:"#gimp-3-0-中值得期待的-8-項新功能和改進","aria-label":"Permalink to “GIMP 3.0 中值得期待的 8 項新功能和改進”"},"​")],-1)),t[26]||(t[26]=p("blockquote",null,[p("p",null,"將帶來重大改進的 GIMP 3.0 是最令人期待的版本之一。根據它最近的開發版本，這是一個預期的功能列表。")],-1)),t[27]||(t[27]=p("p",null,[p("img",{src:"https://i2.wp.com/news.itsfoss.com/wp-content/uploads/2021/11/GIMP-3-0-expected.jpg?w=1200&ssl=1",alt:""})],-1)),p("p",null,[a(s,{href:"https://www.gimp.org/"},{default:o(()=>[...t[0]||(t[0]=[e("GIMP",-1)])]),_:1}),t[2]||(t[2]=e(" 是可在 Linux 上使用的 ",-1)),a(s,{href:"https://itsfoss.com/image-applications-ubuntu-linux/"},{default:o(()=>[...t[1]||(t[1]=[e("最佳免費圖像編輯器",-1)])]),_:1}),t[3]||(t[3]=e(" 之一。不僅僅適用於那些想要 Adobe 套件的免費替代品的用户，許多專業人士也使用 GIMP 進行藝術創作、設計和照片編輯。",-1))]),t[28]||(t[28]=l('<p>儘管 GIMP 提供了許多必要的功能和選項，但在各種平台上已經出現了許多現代替代品，其中在一些方面已經超過了 GIMP。</p><p>不過，GIMP 3.0 可能是一個扭轉局面的版本，它將使 GIMP 成為最好的現代產品之一，可與現有的商業對手相競爭。</p><p>本文將討論預期出現在 GIMP 3.0 版本的功能。</p><h3 id="gimp-3-0-值得期待的頂級功能" tabindex="-1">GIMP 3.0 值得期待的頂級功能 <a class="header-anchor" href="#gimp-3-0-值得期待的頂級功能" aria-label="Permalink to “GIMP 3.0 值得期待的頂級功能”">​</a></h3><p>隨着 GIMP 3.0 的版本發佈，其開發版本增加了很多改進。</p><p>你或許想看到早期開發版本中的所有功能/變化，但我們將在本文中只能介紹其中重要的亮點。</p><h3 id="_1、基於-gtk3-的用户界面" tabindex="-1">1、基於 GTK3 的用户界面 <a class="header-anchor" href="#_1、基於-gtk3-的用户界面" aria-label="Permalink to “1、基於 GTK3 的用户界面”">​</a></h3><p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2021/11/gimp-2-99-2-gtk3.png?w=1200&amp;ssl=1" alt="來源：GIMP Blog"></p><p>GIMP 3.0 將帶來基於 GTK3 的用户界面的重新打造的視覺享受。除了改進的外觀和感受，你還可以看到一些新的小工具。</p>',9)),p("p",null,[t[5]||(t[5]=e("別忘了，",-1)),a(s,{href:"https://news.itsfoss.com/gimp-ui-edward-snowden/"},{default:o(()=>[...t[4]||(t[4]=[e("愛德華•斯諾登也認為 GIMP 需要進行 UI 大修",-1)])]),_:1}),t[6]||(t[6]=e("。所以，GIMP 3.0 即使最終沒有成為一種視覺享受，也應該在某種形式上有所改善。",-1))]),t[29]||(t[29]=l('<p>在以前的 GIMP 版本中，它並不支持高像素密度的顯示器。雖然可以使用，但如果你有一個更高分辨率的屏幕，GIMP 看起來就不夠好。</p><p>現在，隨着 GTK3 的加入，它增加了對高像素密度顯示器的支持。你所要做的就是設置你的操作系統的首選縮放/分辨率，GIMP 應該可以支持它了。</p><h3 id="_2、wayland-支持" tabindex="-1">2、Wayland 支持 <a class="header-anchor" href="#_2、wayland-支持" aria-label="Permalink to “2、Wayland 支持”">​</a></h3><p>向 GTK3 的過渡應該能提供更好的 Wayland 支持。因此，如果你開始使用 Wayland 桌面會話，GIMP 3.0 應該可以讓你毫無問題地使用該應用程序。</p><h3 id="_3、多層選擇" tabindex="-1">3、多層選擇 <a class="header-anchor" href="#_3、多層選擇" aria-label="Permalink to “3、多層選擇”">​</a></h3><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2021/11/gimp-2.99.2-multi-layer-selection.png?w=492&amp;ssl=1" alt="來源：GIMP 播客"></p><p>最關鍵的新增功能之一是可以選擇多個圖層。</p><p>雖然這是一個需要很長時間才能完成的功能，但它終於在 GIMP 3.0 版本中實現了。</p><p>有了這個功能，人們可以輕鬆地管理和組織他們的工程中的幾個圖層。</p><p>根據現有的信息，他們正式提到了這個變化：</p><blockquote><p>可停靠的圖層現在完全可以進行多選，使用通常的交互方式進行多項目選擇（“<code>Shift</code> + 點擊”用於選擇一系列圖層，“<code>Ctrl</code> + 點擊”用於選擇或取消選擇不相鄰的層）。組織操作現在可以對所有選定的圖層起作用，即你可以一次性移動、重新排序、刪除、複製、合併（以及更多...）所有選定的圖層。</p></blockquote><p>換句話説，你可以選擇多個圖層，並同時對它們進行批量操作。</p><p>例如，你可以裁剪、移動、使用合併的圖層中的顏色選擇工具，並使用這個功能執行更多操作。</p><p>在發表這篇文章時，我注意到，根據他們的開發Blog，這是一個正在進行的工作，有一些限制。希望在穩定版中，多層選擇可以完美地工作。</p><h3 id="_4、新的插件-api" tabindex="-1">4、新的插件 API <a class="header-anchor" href="#_4、新的插件-api" aria-label="Permalink to “4、新的插件 API”">​</a></h3><p>插件 API 保留了所有的基本功能，但也引入了一些新的改進。</p><p>因此，新的插件 API 應該不會對開發者造成任何破壞，而應該可以讓他們把插件輕鬆地移植到 GIMP 3.0 應用程序上。</p><p>他們的開發版本中提到了一些改進：</p><ul><li>擺脱了對象 ID，轉而使用真實的對象。特別是在 GIMP 3 中，<code>GimpImage</code>、<code>GimpItem</code>、<code>GimpDrawable</code>、<code>GimpLayer</code>、<code>GimpVectors</code>、<code>GimpChannel</code> 和 <code>GimpPDB</code> 都是對象（其他類別的對象已經存在或以後可能加入）。</li><li>路徑現在被當作 <code>GFile</code> 來處理，這意味着使用 GLib/GIO API。</li><li>GIMP API 應該可以完全支持各種語言（Python 3、JavaScript、Lua、Vala 等）。</li></ul><h3 id="_5、繪畫選擇工具" tabindex="-1">5、繪畫選擇工具 <a class="header-anchor" href="#_5、繪畫選擇工具" aria-label="Permalink to “5、繪畫選擇工具”">​</a></h3><p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2021/11/gimp-paint-select-tool.png?w=800&amp;ssl=1" alt="來源：GIMP Blog"></p><p>前景選擇工具不會消失。然而，他們正在開發一個新的實驗性的“繪畫選擇”工具，它可以讓你逐步選擇和繪製使用畫筆的區域。</p><p>繪畫選擇工具的目的還在於克服前景選擇工具對大圖像的限制，並解決內存/穩定性問題。</p><p>考慮到它被列為實驗性工具，我們不能確定它是否能進入穩定版，但它已經有了新的圖標，你可以找到這個工具。</p><h3 id="_6、windows-ink-支持" tabindex="-1">6、Windows Ink 支持 <a class="header-anchor" href="#_6、windows-ink-支持" aria-label="Permalink to “6、Windows Ink 支持”">​</a></h3><p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2021/11/gimp-windows-ink.png?w=1278&amp;ssl=1" alt="來源：GIMP 播客"></p><p>當然，我們在這裏討論的都是 Linux。但是，GIMP 是一個流行的跨平台工具。</p><p>所以，為了吸引更多的用户，最好為專業人士或設計師使用的工具提供硬件支持。</p><p>GIMP 3.0 現在支持 Windows Ink 開箱即用，這要歸功於它引入的 GTK3。你會從管理輸入設備的設置中找到使用 Windows Ink API 的選項。</p><h3 id="_7、改進手勢支持" tabindex="-1">7、改進手勢支持 <a class="header-anchor" href="#_7、改進手勢支持" aria-label="Permalink to “7、改進手勢支持”">​</a></h3><p>GIMP 並不是筆記本電腦用户的最佳選擇，或者更準確地説，不是觸摸板/觸摸屏用户的最佳選擇。</p><p>然而，隨着 GIMP 3.0 增加了手勢支持，可以捏住畫布放大/縮小，這種情況可能會有所改善。</p><p>我們還可能在最終版本中看到更多的手勢支持，但截至 2.99.8 版本，也就是最新的開發版本，還沒有新的手勢。</p><h3 id="_8、改進的文件格式支持" tabindex="-1">8、改進的文件格式支持 <a class="header-anchor" href="#_8、改進的文件格式支持" aria-label="Permalink to “8、改進的文件格式支持”">​</a></h3><p>GIMP 3.0 現在支持 JPEG-XL 文件格式，能夠加載/導出帶有灰度和 RGB 顏色配置文件的 .jxl 文件。</p><p>對 Adobe Photoshop 工程文件的支持也得到了改進。它現在可以處理大於 4GB 的 PSD 文件，同時加載多達 99 個通道。</p><p>除此以外，對 WebP 和 16 位 SGI 圖像的支持也得到了改進。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>',38)),p("p",null,[t[8]||(t[8]=e("看看 ",-1)),a(s,{href:"https://www.gimp.org/news/2021/10/20/gimp-2-99-8-released/"},{default:o(()=>[...t[7]||(t[7]=[e("GIMP 的開發Blog",-1)])]),_:1}),t[9]||(t[9]=e("，看起來他們幾乎已經完成了最終版本。然而，他們並沒有透露任何特定的發佈日期時間表。",-1))]),t[30]||(t[30]=p("p",null,"所以，一旦他們解決了錯誤並完成了改進，它就會到來。",-1)),t[31]||(t[31]=p("p",null,"你期待 GIMP 3.0 嗎？它看起來是一個有希望的下一代版本嗎？",-1)),t[32]||(t[32]=p("hr",null,null,-1)),p("p",null,[t[11]||(t[11]=e("via: ",-1)),a(s,{href:"https://news.itsfoss.com/gimp-3-0-features/"},{default:o(()=>[...t[10]||(t[10]=[e("https://news.itsfoss.com/gimp-3-0-features/",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=e("作者：",-1)),a(s,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...t[12]||(t[12]=[e("Ankush Das",-1)])]),_:1}),t[17]||(t[17]=e(" 選題：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[13]||(t[13]=[e("lujun9972",-1)])]),_:1}),t[18]||(t[18]=e(" 譯者：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1}),t[19]||(t[19]=e(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[15]||(t[15]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[22]||(t[22]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[20]||(t[20]=[e("LCTT",-1)])]),_:1}),t[23]||(t[23]=e(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:o(()=>[...t[21]||(t[21]=[e("Linux中國",-1)])]),_:1}),t[24]||(t[24]=e(" 榮譽推出",-1))])])}const h=i(m,[["render",P]]);export{b as __pageData,h as default};
